insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5ba6899a-7c48-43f0-9751-4de815468a09', 'fr', 'Un homme veut attendre que sa peur retombe avant d’aborder. Quel est le problème ?', '["Il va rater le moment idéal pour engager la conversation", "La peur reviendra plus forte la prochaine fois", "Il laisse l’anxiété décider à sa place", "La peur se dissout dans l’action, pas en attendant d’être prêt"]'::jsonb, 'La peur ne disparaît ni par la réflexion ni avec le temps ; elle se dissout dans le mouvement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9f9aab5f-516e-467e-859b-ddaecdf461cd', 'fr', 'Que se passe-t-il quand tu abordes malgré la peur ?', '["La douleur prédite arrive toujours", "La confiance exige de ne pas avoir peur avant", "La peur se renforce avec l’exposition", "Le système nerveux enregistre que la menace était fausse"]'::jsonb, 'L’action dément la prédiction, ce qui adoucit les réactions suivantes.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5ce08bb8-9bb3-4d2e-b08c-7b62c8593bb1', 'fr', 'Pourquoi le fait d’être vu paraît-il plus intense qu’il ne l’est ?', '["Les gens regardent vraiment de près", "Le jugement est permanent", "L’esprit exagère l’attention portée à soi", "Les règles sociales sont strictes"]'::jsonb, 'L’esprit surestime à quel point les autres font attention à nous.')
