insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5ef57991-7795-4349-9a51-3c0db95233c6', 'fr', 'Dans une conversation de groupe, l’attention se tourne vers toi. Que fais-tu ?', '["Rester détendu et continuer naturellement", "Te replier sur toi et t’observer", "Forcer l’assurance pour cacher la tension", "Quitter vite la conversation"]'::jsonb, 'Le sang-froid vient du fait d’accepter d’être visible sans résister.')
