insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('28ccfdfd-13b7-4bf5-9d16-e2ade47fa571', 'fr', 'Que signale au corps une respiration superficielle ?', '["La sécurité", "Une menace", "La concentration", "La confiance"]'::jsonb, 'Une respiration rapide signale un danger au corps. Ralentis-la pour te calmer.')
