insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('784400be-2ea4-4606-85a5-fb25457e3b9c', 'fr', 'La pression monte et ton esprit s’emballe avant de parler. Qu’est-ce qui aiderait ?', '["Répéter tes phrases dans ta tête", "Éviter la situation jusqu’à ce que tu sois calme", "Une inspiration régulière et une expiration maîtrisée"]'::jsonb, 'Être attentif à ta respiration rappelle à ton corps que c’est toi qui commandes.')
