insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('81883b1d-a00d-4283-b3fc-38c0192aaff9', 'fr', 'Où vit l’anxiété, et comment l’ancrage aide-t-il ?', '["L’anxiété vit dans les traumatismes passés ; l’ancrage crée de nouvelles expériences", "L’anxiété vit dans le corps ; l’ancrage relâche les tensions physiques", "L’anxiété vit dans les pensées sur l’avenir ; l’ancrage te ramène à la réalité présente"]'::jsonb, 'L’anxiété vit dans les pensées sur l’avenir ; l’ancrage ramène l’attention au corps, dans le présent.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b700e82d-a04f-4ae2-af7e-9af63595b855', 'fr', 'Quels gestes d’ancrage aident à réduire l’anxiété ?', '["Sentir tes pieds sur le sol", "Remarquer le mouvement de ta respiration", "Préparer tes phrases", "Relâcher les épaules"]'::jsonb, 'L’ancrage fonctionne en sortant l’attention de la tête pour la ramener aux sensations physiques.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4cdb8cfc-39c3-4aee-8e46-064ef4dd4976', 'fr', 'Pendant une approche, tu te sens raide, debout. Qu’est-ce qui aide le plus ?', '["Te pencher en avant", "Parler plus lentement", "Faire des blagues", "Relâcher les épaules et respirer"]'::jsonb, 'Détendre d’abord le corps te rend ta présence naturelle pendant l’échange.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('35629852-7dc2-4adf-8383-df72ab56b0fb', 'fr', 'Quel est le lien entre langage corporel et confiance ?', '["Un langage corporel cohérent dans le temps crée la confiance", "Les gens font plus confiance à ce qu’ils voient qu’à ce qu’ils entendent", "Les gens dignes de confiance ont naturellement un langage corporel ouvert et détendu"]'::jsonb, 'Les gens réagissent aux signaux non verbaux avant d’écouter les explications.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('be052099-dc33-4516-be7b-fb7e8a574364', 'fr', 'Pourquoi le langage corporel parle-t-il avant les mots ?', '["Le cerveau lit d’abord les mouvements et la posture pour évaluer la sécurité", "On traite les signaux non verbaux plus vite que les signaux verbaux", "Un décalage entre le corps et les mots se ressent", "Les mots l’emportent toujours sur les signaux physiques"]'::jsonb, 'Le non-verbal est traité instinctivement, avant la logique.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('32686574-8a7a-4a9b-8887-1bf18793907c', 'fr', 'Comment les gens se calent-ils vraiment sur le ton de ta voix ?', '["Si tu as l’air tendu, ils se sentent tendus ; si tu as l’air à l’aise, ils se sentent à l’aise", "Ils remarquent et évaluent consciemment ton état émotionnel", "Les intonations activent des neurones miroirs qui créent de l’empathie"]'::jsonb, 'Les gens reproduisent inconsciemment l’énergie de ta voix. Garde-la calme.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('82c30e7d-5adc-41dc-afc4-5569d6e8fb80', 'fr', 'Quelles façons de parler mettent les autres à l’aise ?', '["Un débit plus lent", "Parler sur l’expiration", "Combler vite les silences", "Un volume régulier"]'::jsonb, 'Un rythme et un souffle réguliers rendent ta voix rassurante et agréable à écouter.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5cdfce0f-0fe8-4f05-b355-7b070e7383bd', 'fr', 'Pourquoi une voix posée influence-t-elle plus qu’une voix forte ?', '["Elle exige l’attention par le volume", "Elle signale inconsciemment la sécurité et l’aisance", "Elle pousse les gens à écouter sans forcer", "Elle donne du poids et un rythme détendu"]'::jsonb, 'Un ton calme attire les gens parce qu’il transmet de la stabilité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6cd4ab05-6a0e-4e05-9ef2-09775c5c9496', 'fr', 'Pourquoi une énergie basse peut-elle faire fuir les autres ?', '["Il est désagréable de s’y accorder", "Elle signale de l’arrogance", "Elle suggère un manque d’intérêt"]'::jsonb, 'On évite instinctivement les états qui paraissent lourds. Garde une énergie positive.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e40cadb9-6906-42bf-b334-b269e634ab6e', 'fr', 'Comment améliorer ton énergie avant d’aborder ?', '["Bouger un peu, sourire, te dire quelques phrases positives", "Analyser la situation plus longtemps", "Attendre que la confiance arrive", "Te retirer pour éviter la tension"]'::jsonb, 'Bouger change vite ton état et fait monter ton énergie.')
