insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d028ed4f-fd88-4a7c-8aab-17f7a78c6a9a', 'fr', 'Quel effet une énergie positive a-t-elle sur tes approches ?', '["Elle attire les gens inconsciemment", "Elle invite naturellement à l’échange", "Elle exige une apparence parfaite"]'::jsonb, 'Une bonne énergie donne envie aux gens de se rapprocher et de se sentir mieux avec toi.')
