insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cfa95ebd-1b35-41c8-8a50-fbcb06fee6aa', 'fr', 'Pourquoi sourire réduit-il la tension sociale ?', '["Il détourne l’attention", "Il déclenche des réactions émotionnelles positives", "Il cache la nervosité"]'::jsonb, 'Quand tu souris, les deux cerveaux enregistrent du positif avant le moindre mot.')
