insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2c9f06f7-4cf4-45f9-80cd-7c8fcac8c28c', 'fr', 'Pourquoi dépendre de l’approbation sape-t-il la confiance ?', '["Ça crée de la pression", "Ça limite l’expression", "Ça trahit un doute sur soi", "Ça affaiblit les limites"]'::jsonb, 'Avoir besoin d’approbation montre que tu ne t’approuves pas toi-même.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7bd56cd8-1f4f-4678-8dce-d3e92a3e8932', 'fr', 'Elle donne un avis avec lequel tu n’es pas d’accord. Qu’est-ce qui évite de chercher son approbation ?', '["Approuver tout de suite pour préserver l’harmonie", "Donner poliment ton avis différent, sans t’excuser", "Changer d’avis pour coller au sien", "Te taire pour éviter le conflit"]'::jsonb, 'Garder calmement ta position montre que tu t’approuves toi-même, sans être en demande.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3fe6a5a2-4f72-4f9a-9d46-3a48ef587e96', 'fr', 'Pourquoi la recherche d’approbation fait-elle fuir l’attirance ?', '["Elle trahit un besoin désespéré de validation", "Elle fait dépendre ta valeur de son acceptation", "Elle crée un manque d’authenticité", "Elle garantit toujours un lien plus profond"]'::jsonb, 'Chercher l’approbation trahit un doute sur soi ; s’accepter montre de la force.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e562de05-8b81-429d-b188-fbe14cf83db2', 'fr', 'Après des mois d’entraînement, un homme est toujours nerveux. Que doit-il mesurer ?', '["Si d’autres progressent plus vite avec autant d’entraînement", "S’il fait aujourd’hui des choses dont il était incapable avant", "Où il en est comparé aux hommes naturellement sûrs d’eux"]'::jsonb, 'La seule mesure qui compte, c’est de savoir si tu fais mieux qu’avant.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('586652d7-39f3-41aa-9a2f-cb693ae30050', 'fr', 'Pourquoi se comparer aux autres est-il destructeur pour progresser ?', '["Tu ne connais ni leur point de départ, ni leur quantité d’entraînement, ni toute leur histoire", "Ça crée des attentes irréalistes qui garantissent l’échec", "Tu compares ton vécu intérieur à leurs résultats visibles, ce qui n’est pas juste"]'::jsonb, 'Tu vois leurs résultats sans connaître leur point de départ ni leur histoire.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9250aace-fa4f-4d66-95e4-793349439200', 'fr', 'Qu’est-ce qui rend l’approche plus légère ?', '["Ne pas laisser le résultat définir qui tu es", "Accepter le rejet comme une étape normale du processus", "Les deux réponses ci-dessus"]'::jsonb, 'Quand le résultat ne décide pas de ta valeur, aborder est moins intimidant.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('53bacb30-3d41-4c17-a18d-8c00b9bc1398', 'fr', 'Que veut dire ne pas dépendre du résultat dans un échange ?', '["Garder ton équilibre émotionnel quelle que soit sa réaction", "Te moquer complètement du résultat", "Forcer un résultat positif à chaque fois", "Éviter les échanges pour rester en sécurité"]'::jsonb, 'Quand ton humeur reste stable quelle que soit la réaction, tu reprends le contrôle.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('83794883-664e-42e0-89fa-abc8d0f95334', 'fr', 'Que signifie vraiment ne pas dépendre du résultat ?', '["Ne pas du tout te soucier du résultat ou de la réussite de l’échange", "Garder ton équilibre émotionnel quelle que soit la tournure de l’échange", "Ta valeur et ton humeur ne dépendent pas d’un résultat précis"]'::jsonb, 'Le résultat compte toujours pour toi, mais il ne dicte plus ce que tu ressens ni ce que tu fais.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('39d1a173-8185-476b-ba48-a86f79e52a48', 'fr', 'Quelle est la clé pour bien gérer une réaction positive ?', '["Faire plus d’efforts pour garder son attention", "Baisser ton énergie pour éviter la pression", "Contrôler le moment pour ne pas le perdre", "Rester la même version de toi qui a suscité son intérêt"]'::jsonb, 'La version de toi qui a créé l’attirance suffit déjà. N’en rajoute pas et ne joue pas un rôle.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3b61bcf4-54dc-4de9-8ba8-813071e2e979', 'fr', 'L’ambiance est super et elle se penche vers toi. Ton esprit commence à gérer « la suite ». Que fais-tu ?', '["Revenir au moment présent sans chercher à contrôler", "Laisser tes pensées prendre le dessus pour planifier", "Aller plus loin très vite pour en profiter", "Te retirer de cette énergie positive"]'::jsonb, 'Quand tout va bien, ton rôle est de garder le rythme, pas de gérer le résultat.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0b5dc6ef-1cda-498e-932d-4939839666ad', 'fr', 'Pourquoi une réaction positive peut-elle déstabiliser ?', '["Elle déclenche une quête de validation née d’une mentalité de pénurie", "Elle active la peur de perdre ce bon sentiment", "Elle ne demande aucun ajustement de comportement", "Elle peut créer une pression pour en profiter et tout contrôler"]'::jsonb, 'Les signaux positifs créent quelque chose à perdre ; évite de passer en mode protection du résultat.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5956bc0c-e67e-486c-9121-0d4f3f555035', 'fr', 'Que change d’abord la forme physique, avant même que les autres remarquent ton corps ?', '["Tes connaissances en entraînement et ta discipline", "L’image que tu as de toi et ta confiance intérieure", "Ta capacité à attirer l’attention", "Ta conversation et ton charme"]'::jsonb, 'La confiance grandit quand le regard que tu portes sur toi s’améliore d’abord.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9ec8b2af-94c5-4b1c-a704-f2bd3e950b20', 'fr', 'Comment la forme physique aide-t-elle à gagner confiance en soi ?', '["Elle est la preuve physique que tu te prends au sérieux", "Elle te rend visiblement attirant pour les femmes", "Elle t’apprend une discipline qui sert aussi en séduction", "Elle te donne du statut en société"]'::jsonb, 'La forme physique change d’abord l’image que tu as de toi, ce qui augmente tes chances d’aborder.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d0c9fead-d08c-463e-82b3-6acbc68aa42b', 'fr', 'D’où vient le gain de confiance lié à une bonne forme physique ?', '["Croire que ton corps est plus capable", "Voir dans le miroir un corps que tu respectes", "T’observer moins en société", "Recevoir des compliments"]'::jsonb, 'Le respect de soi façonne le comportement bien avant que la validation des autres entre en jeu.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('941578b4-3efd-48fd-bb43-567d6cc34570', 'fr', 'Quel effet un manque d’entretien a-t-il sur la première impression ?', '["Les femmes attendent plus d’efforts", "Il signale un statut bas", "Il crée une hésitation avant même que l’attirance naisse"]'::jsonb, 'Les premiers signaux visuels façonnent l’aisance et l’intérêt avant que la conversation commence.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('320c1b55-513d-40ef-8b8a-5575836c5e6c', 'fr', 'Quel est le principal effet intérieur d’une apparence entretenue ?', '["La validation extérieure grâce aux compliments", "Forcer la confiance par la volonté", "Un changement spectaculaire de tes traits", "Te sentir net et soigné sans effort"]'::jsonb, 'Prendre soin de ton apparence change l’image que tu as de toi, ce qui augmente tes chances d’aborder.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c8f3b672-a516-497b-889c-0bb6535c7859', 'fr', 'Quels sont les bénéfices d’une apparence entretenue ?', '["Une meilleure première impression", "Moins de barrières intérieures, donc un comportement plus naturel", "Elle montre que tu te respectes", "Elle te donne un avantage sur les hommes moins soignés"]'::jsonb, 'Une première impression plus nette, un comportement plus libre et un respect de soi visible.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1e694c46-0fd5-4820-84c0-2432a8fd7227', 'fr', 'En quoi une bonne hygiène aide-t-elle à aborder ?', '["Elle supprime de petites barrières qui gênent l’attirance", "Elle montre que tu fais attention aux autres", "Elle garantit que tu sens meilleur que les autres hommes", "Elle crée à chaque fois une première impression soignée"]'::jsonb, 'L’hygiène supprime une friction invisible qui crée de la distance.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d0aa5e3a-b58e-4eea-8381-e21cbca6f874', 'fr', 'Qu’apporte vraiment une bonne hygiène ?', '["Elle supprime les barrières qui empêchent l’attirance de naître", "Elle te donne une certitude intérieure pour te rapprocher", "Elle te rend plus charmant et plus doué en société"]'::jsonb, 'Être sûr de ton hygiène met fin à l’autosurveillance et aux barrières invisibles qui créent de la friction.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9b201136-be01-4de3-b7a9-41ab4fa02a38', 'fr', 'Pourquoi un mauvais style crée-t-il une friction invisible ?', '["Il casse le fil de la conversation", "Il fait perdre de l’assurance à ta voix", "Il oriente négativement les premiers jugements", "Il donne une image d’introverti"]'::jsonb, 'Les premiers jugements influencent l’ouverture avant même que l’échange commence vraiment.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c3ef8c23-3bd4-42a1-ba4a-0cc007c4f952', 'fr', 'Quel effet un bon style a-t-il sur ta confiance intérieure ?', '["Il améliore ton humour", "Il renforce ta domination", "Il te distrait moins de toi-même", "Il réduit l’autosurveillance"]'::jsonb, 'Des vêtements dans lesquels tu te sens bien gardent ton attention tournée vers l’extérieur plutôt que vers toi.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('02e91b80-7376-4e58-a593-604cc6b23a79', 'fr', 'Ton rire sonne forcé et ta voix monte dans les aigus. Quel exercice aide ?', '["Parler plus fort en inspirant", "Monter dans les aigus pour plaire", "Prendre un instant avant chaque idée et parler sur l’expiration", "Accélérer pour suivre ta nervosité"]'::jsonb, 'Un débit maîtrisé sur l’expiration pose ta voix et ta présence.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('03af7107-7650-4d54-b1a7-e9dee067e1b1', 'fr', 'Quand quelqu’un commence à s’observer, qu’est-ce qui change dans l’échange ?', '["Le rôle joué remplace le lien", "L’expression diminue", "L’anxiété disparaît"]'::jsonb, 'S’observer détourne l’attention d’un échange sincère.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0cfb0ca8-28d9-426f-80c4-d26b972acc51', 'fr', 'Un homme se repasse une conversation et décide qu’il a eu l’air gauche. Que se passe-t-il ?', '["Il tire des leçons de ses erreurs pour progresser", "Il est réaliste sur sa performance sociale", "Son esprit comble les vides avec de la peur, pas avec des faits", "Sa lucidité l’aide à repérer ses points faibles"]'::jsonb, 'L’histoire que ton esprit raconte après coup n’est pas un compte rendu fiable de ce qui s’est passé.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1050b192-a012-4512-86fb-9ceb4d8087e7', 'fr', 'Quels effets un sourire sincère peut-il créer ?', '["Moins de stress", "Un air plus abordable", "Une garde qui se baisse", "Une attirance immédiate"]'::jsonb, 'Un sourire sincère montre de la chaleur avant que la conversation commence.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1078c50b-deac-4399-9cc9-3872de90104c', 'fr', 'Quel est le changement de fond derrière la confiance en soi ?', '["Être admiré", "Être impressionnant", "Être accepté", "Ne plus avoir besoin de preuves"]'::jsonb, 'La confiance se stabilise quand ta valeur ne dépend plus des autres.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1d689f0a-9831-4f51-86c0-26f91d7c3192', 'fr', 'Pourquoi l’ancrage réduit-il l’anxiété avant d’aborder ?', '["Il détourne temporairement ton esprit des pensées anxieuses", "Les sensations physiques signalent la sécurité, ce qui désactive la réaction de menace", "Se concentrer sur son corps renforce la confiance par la prise de conscience"]'::jsonb, 'L’ancrage fonctionne en sortant l’attention de la tête pour la ramener aux sensations physiques.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('219e0cdc-a9ad-455f-86bd-5424943faf26', 'fr', 'Un homme reçoit un signe positif et pense aussitôt « Ne gâche pas tout ». Que se passe-t-il ?', '["La pression l’aide à éviter les erreurs", "Il crée une pression qui change son énergie", "Cette pensée le motive à rester impliqué"]'::jsonb, 'Chercher à ne pas échouer remplace un échange détendu et abîme la complicité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('259c1e7d-ff03-4cbb-8e6f-491608175612', 'fr', 'Que fait vraiment une énergie positive ?', '["Elle attire les gens parce qu’ils se sentent mieux avec toi", "Elle crée une attirance immédiate par des signes de statut élevé", "Elle rend tes mots plus convaincants", "Elle facilite l’échange"]'::jsonb, 'Une énergie positive fait du bien aux gens, ce qui les attire naturellement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2aba3577-76b4-423a-898b-cb6e1f03d88d', 'fr', 'Pendant une approche, un homme parle vite, d’une voix plus aiguë. Que se passe-t-il ?', '["Son enthousiasme passe pour de la nervosité", "Son ton trahit une tension qu’elle sent avant d’entendre ses mots", "Il essaie inconsciemment de combler les silences et de garder l’élan"]'::jsonb, 'Quand le ton est précipité ou forcé, les gens sentent la tension.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('35e59aa9-31b1-4b02-af42-50fe8b4a375c', 'fr', 'Un homme choisit mal ses mots, mais a une super énergie. Que se passe-t-il ?', '["L’échange reste agréable", "La conversation échoue", "L’intérêt retombe vite", "Les gens se focalisent sur ses erreurs"]'::jsonb, 'Quand ton énergie est positive, les gens aiment être avec toi.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('40266254-315c-41fe-9eba-7ad6413d86a3', 'fr', 'Pourquoi un sourire marche-t-il mieux que les mots au début ?', '["Les mots paraissent risqués", "Les visages sont traités plus vite", "Un sourire montre clairement ton intention", "Le silence paraît assuré"]'::jsonb, 'Le cerveau lit les visages avant le langage. Souris d’abord, laisse ton sourire t’aider.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('43d2d9f6-2ffb-4330-8584-9a58b70d6399', 'fr', 'Pourquoi la forme physique renforce-t-elle la confiance au-delà de l’apparence ?', '["Elle change immédiatement la façon dont les autres te perçoivent", "Elle améliore l’image que tu as de toi et le respect de ton corps", "Elle réduit l’autosurveillance et le doute"]'::jsonb, 'La forme physique façonne tes convictions intérieures et réduit le bruit, ce qui renforce une confiance naturelle.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('46eb84b4-53da-484e-8846-fdb26ae3c785', 'fr', 'Qu’est-ce qui renforce la confiance sur la durée ?', '["Des émotions calmes", "Des plans clairs", "Éviter l’inconfort", "Agir malgré la peur"]'::jsonb, 'La confiance se forme après s’être lancé, pas avant.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4ac6998e-65dd-431c-99de-be7a3f97072e', 'fr', 'Pendant une approche, tes épaules se crispent et ton regard fuit. Quelle est ta priorité ?', '["Supprimer les signes de tension en relâchant ta posture et ta respiration", "Parler plus vite pour couvrir la nervosité", "Forcer un regard plus intense", "Faire de grands gestes pour avoir l’air sûr de toi"]'::jsonb, 'Ton corps transmet la sécurité ou la tension avant même tes mots.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51ceb33f-6d3d-4110-8369-52ab53cc3b2c', 'fr', 'Elle montre un fort intérêt, et tu ressens le besoin de « ne pas tout gâcher ». Quel état d’esprit aide ?', '["Cette occasion rare doit être assurée", "Te retirer pour ne prendre aucun risque", "En faire plus pour mériter le moment", "Son intérêt fait plaisir ; reste celui qui lui a plu"]'::jsonb, 'Remarque son intérêt sans t’y accrocher ni en réclamer plus.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5423b03c-3be1-4925-81c1-77d8776ea860', 'fr', 'Après un regard échangé, tu marches vers elle. Quelle expression aide le plus ?', '["Un visage neutre et sérieux", "Un grand sourire forcé", "Un sourire chaleureux et sincère, que tu gardes", "Aucune expression, pour rester cool"]'::jsonb, 'Un sourire sincère signale la sécurité avant le moindre mot.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('59af149f-a4e1-4e59-9e5c-79c015952617', 'fr', 'Un échange se passe mal. Que dois-tu penser ?', '["« Ça n’a pas marché, qu’est-ce que je peux ajuster la prochaine fois ? »", "« Je suis vraiment nul pour ça. »", "« Certains sont doués d’office ; pas moi. »", "« Je devrais arrêter d’essayer. »"]'::jsonb, 'L’état d’esprit de développement fait du refus une donnée pour progresser.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6050d9fa-5758-4a66-9d2a-4484751813c5', 'fr', 'Quand l’attention est sur lui, un homme essaie de contrôler l’image qu’il donne. Quel est le prix ?', '["Il paraît moins sûr de lui et plus mal à l’aise", "Les gens remarquent le rôle qu’il joue et réagissent mal", "Gérer son image le rend moins authentique et plus dans le rôle"]'::jsonb, 'Plus tu essaies de contrôler l’image que tu donnes, moins tu es authentique.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('695eb047-3678-474b-a13a-26682bf11d5f', 'fr', 'Tu entres dans un bar les bras croisés, avec peu d’énergie. Que se passe-t-il ensuite ?', '["Les gens viennent vers toi avec enthousiasme", "Tu te détends avec le temps", "Les gens t’évitent sans s’en rendre compte", "Tes mots ont plus de poids"]'::jsonb, 'Un langage corporel fermé signale le repli, même si tu as envie de créer du lien.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6e9907b3-8130-4125-a5aa-e6b1a0898b60', 'fr', 'Qu’est-ce qui détermine les progrès en compétences sociales sur la durée ?', '["Le talent naturel dès le départ", "Croire que les capacités se développent par la pratique", "Continuer à faire des efforts malgré les échecs", "Éviter les défis pour protéger ta confiance"]'::jsonb, 'Les compétences ne se développent que si tu n’abandonnes pas et que tu continues.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7ea9a0ee-49fd-4682-8888-bb7fba4dfa72', 'fr', 'En pleine discussion, tes bras restent croisés et ta posture s’affaisse. Qu’est-ce que ça montre ?', '["Un malaise qui te replie sur toi, malgré tes mots", "Une présence forte et assurée", "Une énergie détendue et facile", "Un air mystérieux voulu"]'::jsonb, 'Un corps tendu contredit l’aisance de tes mots et crée un décalage.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7f2e5b24-f05e-439d-9f03-8ea8d846f05a', 'fr', 'Tu te sens sans énergie avant d’entrer dans un bar. Qu’est-ce qui pourrait te remettre d’aplomb ?', '["Rester dans un coin jusqu’à ce que ça aille mieux", "Forcer une conversation plus bruyante", "Bouger et sourire volontairement", "Éviter les échanges jusqu’à ce que ça vienne naturellement"]'::jsonb, 'De petits gestes rendent ton énergie positive et accueillante.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('80156644-8f30-46b7-9f70-3e7b0fbd786f', 'fr', 'Ta poitrine se serre et ton esprit s’emballe au moment de parler. Quelles techniques d’ancrage aident ?', '["Penser en boucle à un résultat positif", "Forcer des sujets de conversation plus profonds", "Éviter la situation jusqu’à être plus calme", "Sentir tes pieds au sol et ralentir ta respiration"]'::jsonb, 'L’ancrage fonctionne parce qu’il fait passer ton attention des pensées sur l’avenir aux sensations présentes.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('82bb1ff8-f12d-487b-9b54-090588f0d69d', 'fr', 'Pourquoi une réaction positive donne-t-elle parfois plus d’adrénaline qu’un rejet ?', '["La réussite est naturellement plus intense émotionnellement que l’échec", "Le système nerveux réagit plus fort aux récompenses qu’aux menaces", "Elle crée une nouvelle peur : celle de perdre l’occasion"]'::jsonb, 'Les signaux positifs créent quelque chose à perdre ; évite de passer en mode protection du résultat.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8a5e8c45-7476-413e-8358-7c92cdbab538', 'fr', 'Qu’est-ce qui affaiblit la peur avec le temps ?', '["Te parler positivement avant les moments de pression", "Agir malgré le signal, ce qui met le système à jour", "Chaque approche qui ne se solde pas par la douleur prédite", "Le mouvement plutôt que la réflexion ou la préparation mentale"]'::jsonb, 'La peur s’adoucit quand l’action prouve que les prédictions étaient fausses.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8dc6c797-1c0b-443d-ab04-062afc92c412', 'fr', 'Que se passe-t-il quand tu n’as plus besoin d’approbation ?', '["Ta confiance devient plus stable", "L’attention diminue", "Les échanges raccourcissent", "Tu perds le contrôle"]'::jsonb, 'Ta valeur ne dépend pas de la validation des autres.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8f1849bb-0b9f-4680-afff-7f0d273e5810', 'fr', 'Quels signaux physiques influencent la première impression ?', '["Le regard", "Les pensées intérieures", "La posture"]'::jsonb, 'Les signaux visibles façonnent la perception instantanément.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('94983000-db09-40ee-ac8e-75de9d87d3f6', 'fr', 'Que se passe-t-il quand tu agis malgré la peur ?', '["Le doute grandit faute d’action", "Le cerveau apprend que la peur n’a pas le dernier mot", "La conviction se renforce par l’exposition", "La confiance naît du fait de le faire quand même"]'::jsonb, 'S’en sortir encore et encore fournit à l’esprit des preuves fiables.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9c28c269-1ab6-4f2a-9043-22fadc730b6b', 'fr', 'Tu hésites à aborder, mais tu y vas quand même, et rien de grave n’arrive. Qu’est-ce que ça produit ?', '["Une petite preuve que ton cerveau garde pour te faire confiance à l’avenir", "Une confiance parfaite immédiate", "Un simple soulagement temporaire"]'::jsonb, 'Chaque fois que tu agis quand même, tu enrichis un historique sur lequel tu peux t’appuyer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a0b5f46b-7b16-4682-b089-7e8d882d5dea', 'fr', 'En quoi sourire aide-t-il la personne qui sourit ?', '["Ça améliore la posture", "Ça libère des substances apaisantes", "Ça renforce la domination"]'::jsonb, 'Sourire change ton état intérieur grâce à des substances chimiques que libère le cerveau. Souris plus.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a7253e20-5530-468a-a086-0f0e27b02b4b', 'fr', 'Pourquoi l’évitement augmente-t-il la peur avec le temps ?', '["Il apprend au corps qu’éviter est plus sûr", "Il renforce la réaction de peur, faute d’exposition", "Il construit peu à peu la confiance"]'::jsonb, 'Reculer renforce la boucle d’évitement et le signal de peur.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b400f47c-56f1-455f-8258-5bf582c021f8', 'fr', 'Tu es nerveux, mais tu veux paraître détendu. Qu’est-ce qui accorde ton corps à ton intention ?', '["Te tenir droit, respirer pleinement et moins t’interrompre toi-même", "Croiser les bras pour te protéger", "Éviter le regard pour réduire la pression", "Gigoter pour évacuer l’énergie"]'::jsonb, 'Un corps ouvert et stable reflète le calme sans jouer un rôle.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b505f110-e322-4bf1-9300-fb0cc533a552', 'fr', 'Un doute surgit : « Elle ne va pas m’apprécier. » Que fais-tu ?', '["Le reconnaître comme du bruit et le laisser passer sans y croire", "Combattre ce doute pour prouver qu’il a tort", "Y croire pour rester réaliste", "Te le repasser pour l’analyser en profondeur"]'::jsonb, 'Tu ne contrôles pas les pensées qui surgissent, mais tu contrôles le fait de les croire ou non.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b8441682-aa6b-4a9b-b7ac-97e0f2c1573d', 'fr', 'Pourquoi une énergie positive attire-t-elle les échanges ?', '["Les gens se sentent mieux à son contact", "Elle signale la domination", "Elle exige l’attention"]'::jsonb, 'Les états agréables attirent naturellement les gens. Garde une énergie positive.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b8999272-dae6-4926-b567-a975478a321d', 'fr', 'Qu’est-ce qui casse le lien avant même que la conversation commence ?', '["Un regard fuyant et une posture fermée qui trahissent l’incertitude", "Un corps tendu qui affiche le malaise pendant que les mots paraissent détendus", "Une mauvaise phrase d’accroche ou une technique maladroite"]'::jsonb, 'Les signes physiques de malaise cassent le lien, quels que soient les mots.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c5d60b8c-c34d-4089-81c4-a5f56034f361', 'fr', 'Tu entres dans une pièce bondée et tu sens tous les regards sur toi. Que dois-tu te rappeler ?', '["Tout le monde te juge sévèrement", "Tu dois être parfait pour t’intégrer", "La plupart des gens sont occupés par eux-mêmes, pas par toi", "Te cacher jusqu’à ce que la sensation passe"]'::jsonb, 'L’esprit exagère l’attention ; en réalité, on te regarde bien moins que tu ne le crois.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c8828ffa-d37b-4033-9da0-bd56a61641e5', 'fr', 'La conversation coule parfaitement et elle montre un intérêt clair. Qu’est-ce que tu dois éviter ?', '["Continuer naturellement, dans le moment", "Répondre à ses signaux positifs", "Laisser le rythme respirer", "Faire plus d’efforts pour obtenir plus de validation"]'::jsonb, 'La pression de la recherche d’approbation casse la fluidité naturelle.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c918a4eb-10ec-4f35-a8de-8627f329a218', 'fr', 'En pleine conversation, ta poitrine se serre et ta respiration devient courte. Sur quoi te concentrer ?', '["Forcer ta voix à paraître calme", "Revenir à une respiration régulière et maîtrisée", "Mettre fin à l’échange pour récupérer", "Parler plus vite pour en finir"]'::jsonb, 'Réguler ta respiration pose ta voix avant même que tu essaies de poser tes mots.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dc39682a-160f-459c-a7c6-83758e6a8ad3', 'fr', 'Quel est le principal bénéfice d’un entraînement physique régulier ?', '["Une apparence parfaite pour être validé par les autres", "L’image que tu as de toi et ta confiance intérieure en profitent", "Des changements physiques spectaculaires immédiats", "Forcer la confiance par la volonté"]'::jsonb, 'Un corps que tu respectes crée une assurance intérieure sans effort.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e0b7ae70-05c8-4c9c-8a5b-c48a3e0f6743', 'fr', 'Ton corps se tend avant d’aborder quelqu’un. Qu’est-ce que ça signale ?', '["De la biologie, et une occasion de grandir", "Une faiblesse, et une raison d’arrêter", "Un résultat négatif garanti", "Que tu ne seras jamais prêt"]'::jsonb, 'La peur est une réaction physiologique normale, pas un panneau stop. Bouger prouve qu’elle a tort.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e172e286-a34d-4fba-a51e-7a29d03e5107', 'fr', 'Elle rit facilement, se rapproche et te touche le bras. Que fais-tu ensuite ?', '["Monter en énergie et faire plus d’efforts pour l’impressionner", "Commencer à réfléchir à quoi dire pour que tout reste parfait", "Rester détendu et continuer comme avant", "Aller tout de suite plus loin pour concrétiser"]'::jsonb, 'Un intérêt positif n’est pas un signal pour en faire plus ; c’est un signal pour rester le même.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e56ee826-cd5b-4fb6-8005-84e669a0b1d7', 'fr', 'Pourquoi la respiration aide-t-elle quand la peur surgit avant une approche ?', '["Elle te distrait de la peur", "Elle ralentit le moment", "Elle donne confiance instantanément", "Elle signale la sécurité au système nerveux"]'::jsonb, 'Une respiration lente dit au corps qu’il est en sécurité et calme ton état avant d’agir.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e750c943-9bb0-4a66-892d-3442f22cd528', 'fr', 'Pourquoi le charme peut-il échouer quand le corps est tendu ?', '["L’attirance s’estompe vite", "Les mots perdent leur sens", "Le timing paraît décalé", "Les signaux visuels l’emportent sur la parole"]'::jsonb, 'Le cerveau se fie à ce qu’il voit, pas à ce qu’il entend.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e9e55ffe-f94e-4155-a34b-977fd5d465ba', 'fr', 'Comment la confiance se construit-elle principalement ?', '["Par la pensée positive et les paroles rassurantes", "Par des traits de personnalité naturels", "En accumulant des preuves par des actions répétées", "En évitant les risques jusqu’à être prêt"]'::jsonb, 'La confiance grandit avec la preuve qu’on s’en est sorti en agissant, pas avec l’imagination.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ec90b480-b289-4b95-82b0-39d6020cb7dc', 'fr', 'Quelle est la différence entre les hommes naturellement sûrs d’eux et ceux qui hésitent ?', '["Les hommes sûrs d’eux ont accumulé plus de preuves par la répétition", "Les traits de personnalité déterminent le niveau de confiance de base", "Les hommes sûrs d’eux ont appris plus tôt à croire en eux"]'::jsonb, 'La différence, ce sont les preuves accumulées ; l’un a un historique sur lequel il peut compter.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f030a547-86d7-4259-a4ec-1734e65a10e0', 'fr', 'Une conversation patine et devient gênante. Que dois-tu penser ?', '["« Je ne progresserai jamais. »", "« L’échec prouve que j’ai un défaut. »", "« Ce n’est pas fait pour moi. »", "« C’est une information : qu’est-ce que je peux ajuster la prochaine fois ? »"]'::jsonb, 'L’état d’esprit de développement voit les revers comme ajustables, ce qui te garde dans la partie.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f41af47d-77fc-439e-bcbf-15e75a29eceb', 'fr', 'Quelles actions peuvent faire monter ton énergie avant d’aborder ?', '["Bouger", "Ruminer sur le résultat", "Te replier socialement", "Sourire volontairement"]'::jsonb, 'De petits changements physiques modifient vite ton état intérieur.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f8818fc9-4dc5-4af7-90ed-aa3dc88ca60d', 'fr', 'Tu tournes en boucle sur un possible rejet. Sur quoi te concentrer pour t’aider ?', '["Les sensations immédiates, comme ta respiration ou tes pieds au sol", "Préparer une réponse pour chaque scénario", "Juger ton anxiété comme une faiblesse"]'::jsonb, 'La réalité physique présente détourne l’attention des peurs sur l’avenir.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('faacab86-d6dc-4688-a30c-5fa3c018c113', 'fr', 'Tu veux paraître plus ouvert aux autres. Que dois-tu ajuster en premier ?', '["Préparer des phrases d’accroche parfaites", "Répéter des compliments", "Attendre que les autres viennent vers toi", "Rendre ton énergie positive et ouverte"]'::jsonb, 'Une énergie positive invite les autres à venir avant même les premiers mots.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ff0646b8-d942-49bb-841f-2415d6f99442', 'fr', 'Tu soutiens un regard plus longtemps que d’habitude, et ça se passe bien. Que dois-tu en retenir ?', '["C’était de la chance, pas une preuve", "Une seule fois, ça ne compte pas", "Une preuve discrète que tu peux te faire confiance dans des moments semblables"]'::jsonb, 'Les petits gestes enrichissent l’historique sur lequel ton cerveau s’appuie pour avoir confiance.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
